int count_occurrences(int a[], int n, int x) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] == x) {
            count++;
        }
    }
    return count;
}

int count_occurrences(int a[], int n, int x) {
    int count = 0;
    int i = 0;
    while (i < n) {
        if (a[i] == x) {
            count++;
        }
        i++;
    }
    return count;
}

int count_occurrences(int a[], int n, int x) {
    int count = 0;
    int i;
    for (i = n - 1; i >= 0; i--) {
        if (a[i] == x) {
            count = count + 1;
        }
    }
    return count;
}
